#include <stdio.h>
#include <stdlib.h>
int i;
int rA=0,rB=0,r=0;
int merge(int ar[],int start,int n){
    int temp[n],k,i=start,j=start+n/2;
    int lim_i=start+n/2,lim_j=start+n;
    for(k=0;k<n;k++){
        if((i<lim_i)&&(j<lim_j)){    //both active
            if(ar[i]<=ar[j]){
                temp[k]=ar[i];
                i++;
            }

            else{
               temp[k]=ar[j];
               rA++;
               j++;
            }
        }
    else if(i==lim_i){         //1st half done
        temp[k]=ar[j];     //copy 2nd half
        j++;
    }  
        else{  //2nd half done
        temp[k]=ar[i];      //copy 1st half
        r++;
        i++;
    }
    }
    for(k=0;k<n;k++){
        ar[start+k]=temp[k];   //in place
    }
}

void merge_sort(int ar[],int start,int n){
    if(n>1){
        int half=n/2;
        merge_sort(ar,start, half);
        merge_sort(ar,start+half,n-half);
        merge(ar,start,n);
    }
}
int main(){
    int n;
    scanf("%d\n",&n);
    int* ar;
    ar=(int*)malloc(n*sizeof(int));
    for(i=0;i<n;i++){
        scanf("%d ",&ar[i]);
    }
    merge_sort(ar,0,n);
    printf("%d\n",rA+rB+r);
    for(i=0;i<n;i++){
        printf("%d ",ar[i]);
    }
    return 0;
}

#include<stdio.h>

void merge(int a[],int start,int n)
{
    int t[n],k,i,j,lim_i,lim_j;
    i=start;
    j=start+n/2;
    lim_i=start+n/2;
    lim_j=start+n;
    for(k=0;k<n;k++)
    {
        if(i<lim_i&&j<lim_j)
        {
            if(a[i]<=a[j])
            {
                t[k]=a[i];
                i++;
            }
            else
            {
                t[k]=a[j];
                j++;
            }
        }
        else if(i==lim_i)
        {
            t[k]=a[j];
            j++;
        }
        else
        {
            t[k]=a[i];
            i++;
        }
    }
    for(k=0;k<n;k++)
    {
        a[start+k]=t[k];
    }
}
void m_sort(int a[],int start,int n)
{
    if(n<=1)
    {
        return;
    }
    int half=n/2;
    m_sort(a,start,half);
    m_sort(a,start+half,n-half);
    merge(a,start,n);
}
int main()
{
    int n;
    scanf("%d",&n);
    int a[n];
    int i=0;
    while(i<n)
    {
        scanf("%d",&a[i]);
        i++;
    }
    int count=0;
    int x,y;
    x=0;
    y=0;
    while(x<n)
    {
        while(y<n&&x<y)
        {
            if(a[x]>a[y])
            {
                count++;
            }
            y++;
        }
        x++;
    }
    printf("%d\n",count);
    i=0;
    m_sort(a,0,n);
    while(i<n)
    {
        printf("%d ",a[i]);
        i++;
    }
    return 0;
}
